    expect(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B", "terms": "3", "contact": " Ada@x "})).toBeNull();
    const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "B", "terms": "20"}));
    expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C", "contact": " Ada@x "})).toBeNull();
    expect(await ui.importPeople(pg_uma, "Dot,C\nFay,C,3,")).toMatchObject({"added": 2});
    const p_dot = await ui.personId(pg_uma, "Dot");
    const p_fay = await ui.personId(pg_uma, "Fay");
    expect(await ui.importPeople(pg_uma, "Eve,B")).toMatchObject({"added": 1});
